mapper.select:
select profile_visibility
from users
where id = #{userId}

select content_id, tag, sort_order from content_tags where content_id in
#{contentId}
order by content_id, sort_order

select content_id, word as tag, sort_order from content_recommend_words where content_id in
#{contentId}
order by content_id, sort_order

select content_id, kind, quality, url, storage_key, delivery_type, sort_order from media_assets where content_id in
#{contentId}
order by content_id, sort_order

select kind, quality, url, storage_key from media_assets where content_id = #{contentId} and kind = #{kind}
and coalesce(delivery_type, 'progressive') = 'progressive'
order by sort_order limit 1

select count(*)
from users
where id = #{userId}
